import sqlite3
db = sqlite3.connect(":memory:")
db.executescript('''
CREATE TABLE p(sku TEXT);
CREATE TABLE s(sku TEXT);
INSERT INTO p VALUES ('A'),('B'),('C');
INSERT INTO s VALUES ('A'),(NULL);
''')
a = db.execute("SELECT COUNT(*) FROM p WHERE sku NOT IN (SELECT sku FROM s)").fetchone()[0]
b = db.execute('''SELECT COUNT(*) FROM p WHERE NOT EXISTS
  (SELECT 1 FROM s WHERE s.sku = p.sku)''').fetchone()[0]
print(a, b)

import sqlite3
db = sqlite3.connect(":memory:")
db.executescript('''
CREATE TABLE c(id INT);
CREATE TABLE o(cid INT);
INSERT INTO c VALUES (1),(2);
INSERT INTO o VALUES (1),(1),(1);
''')
j = db.execute("SELECT COUNT(*) FROM c JOIN o ON o.cid = c.id").fetchone()[0]
i = db.execute("SELECT COUNT(*) FROM c WHERE id IN (SELECT cid FROM o)").fetchone()[0]
print(j, i)

